package com.drivique.api.service;
import com.drivique.api.model.Payment; import com.google.zxing.BarcodeFormat; import com.google.zxing.client.j2se.MatrixToImageWriter; import com.google.zxing.common.BitMatrix; import com.google.zxing.qrcode.QRCodeWriter; import org.openpdf.text.*; import org.openpdf.text.pdf.PdfWriter; import java.io.ByteArrayOutputStream; import java.math.*; import org.springframework.stereotype.Service;
@Service public class PaymentReceiptPdfService { public byte[] generate(Payment payment,String number){try{ByteArrayOutputStream out=new ByteArrayOutputStream(); Document doc=new Document(PageSize.A4,50,50,50,50); PdfWriter.getInstance(doc,out); doc.open(); Font title=FontFactory.getFont(FontFactory.HELVETICA_BOLD,18); doc.add(new Paragraph("DRIVIQUE — COMPROBANTE DE PAGO",title)); doc.add(new Paragraph("Consecutivo: "+number)); doc.add(new Paragraph("Referencia: "+payment.getGatewayReference())); doc.add(new Paragraph("Cliente: "+payment.getContract().getCustomer().getFullName())); doc.add(new Paragraph("Método: "+payment.getPaymentMethod().getCode())); BigDecimal net=payment.getAmount().divide(new BigDecimal("1.19"),2,RoundingMode.HALF_UP); BigDecimal tax=payment.getAmount().subtract(net); doc.add(new Paragraph("Subtotal: COP "+net)); doc.add(new Paragraph("IVA (19%): COP "+tax)); doc.add(new Paragraph("Total pagado: COP "+payment.getAmount())); doc.add(new Paragraph("Fecha de pago: "+payment.getPaidAt())); ByteArrayOutputStream qrBytes=new ByteArrayOutputStream();BitMatrix matrix=new QRCodeWriter().encode("DRIVIQUE|"+number+"|"+payment.getGatewayReference(),BarcodeFormat.QR_CODE,110,110);MatrixToImageWriter.writeToStream(matrix,"PNG",qrBytes);Image image=Image.getInstance(qrBytes.toByteArray());image.setAlignment(Image.ALIGN_RIGHT);doc.add(image);doc.close();return out.toByteArray();}catch(Exception e){throw new IllegalStateException("No fue posible generar el comprobante PDF.",e);}} }
